// Score answers carry confidence directly.
// Noul (yes/no) answers derive it from
// distance-from-0.5 — near 0.5 means unsure.
const FLOOR = 0.6;

function verdict(row) {
  if (row.confidence < FLOOR) return 'REVIEW';
  return row.bad ? 'FLAG' : 'OK';
}

